            var textXXXXXXS = 4f;
            var textXXXXXS = 4.5f;
            var textXXXXS = 5f;
            var textXXXS = 5.5f;
            var textXXS = 6f;
            var textXS = 6.5f;
            var textMD = 7f;
            var textLG = 8f;
            var textColor = "#60615b";
            var borderColor = "#bababa";
            var borderSize = 1f;
            var titleSize = textXXXXS;

            QRCodeGenerator qrGenerator = new QRCodeGenerator();
            QRCodeData qrCodeData = qrGenerator.CreateQrCode("https://e-factura.sunat.gob.pe/v1/contribuyente/gre/comprobantes/descargaqr?hashqr=", QRCodeGenerator.ECCLevel.H);
            QRCode qrCode = new QRCode(qrCodeData);
            byte[] qrBytes;
            byte[] verificadoBytes = Convert.FromBase64String(imgVerificado);
            byte[] logoCarolinaBytes = Convert.FromBase64String(imgLogoCarolina);

            using (var qrImage = qrCode.GetGraphic(20))
