                                                    .BorderColor(borderColor)
                                                    .CornerRadius(0)
                                                    .Padding(8)
                                                    .MinHeight(26)
                                                    .Row(row =>
                                                    {
                                                        row.RelativeItem()
                                                            .AlignMiddle() 
                                                            .Column(col1 =>
