                                                                col1.Item().Text($"{_dto.Remitente?.Address}, {_dto.Remitente?.Ubigeo?.Departamento} - {_dto.Remitente?.Ubigeo?.Provincia} - {_dto.Remitente?.Ubigeo?.Distrito}")
                                                                    .AlignCenter();

                                                                if (_dto.Destinatario?.Entity.DocumentTypeId != 1)
                                                                {
                                                                    col1.Item().Text("");
                                                                    col1.Item().Text(text =>
