                                                                        text.Span("RUC y COD. DE ESTABLECIMIENTO: ").SemiBold();
                                                                        text.Span($"{_dto.Remitente?.Entity?.DocumentNumber} - {_dto.Remitente?.CodeSunat}");
                                                                    });
                                                                }
                                                            });
                                                    });

