                                        row.RelativeItem()
                                            .Column(col =>
                                            {
                                                col.Item()
                                                    .PaddingLeft(8)
                                                    .PaddingRight(8)
                                                    .PaddingBottom(5)
                                                    .Column(col =>
                                                    {
                                                        col.Item().Text("PUNTO DE LLEGADA:").FontSize(titleSize).SemiBold();
