                        // Filas dinámicas
                        foreach (var (item, index) in _dto.GuiaDetalles.Select((x, i) => (x, i)))
                        {
                            void cell(string text, string align = "left")
                            {
                                var baseCell = table.Cell()
                                    .Border(borderSize / 2)
                                    .BorderColor(borderColor)
                                    .PaddingTop(5)
                                    .PaddingBottom(5)
                                    .PaddingLeft(3)
