                                        break;
                                    case "right":
                                        baseCell.AlignRight();
                                        break;
                                    default:
                                        baseCell.AlignLeft();
                                        break;
                                }
                            }
                                


                            cell((index +1).ToString(), "center");
                            cell(item.Cantidad, "center");
                            cell(item.UnidadMedida.Descripcion, "center");
                            cell(item.Codigo, "center");
                            cell(item.Descripcion);
                            cell(item.CodigoSunat ?? "");
                            cell(item.Gtin ?? "");
                            cell(item.IndicadorBienNormalizado ? "SI" : "");
                        }
                    });

                    // Observacion
                    col.Item().Column(colObs =>
                    {
                        colObs.Spacing(2);
                        colObs.Item().Text("OBSERVACIONES").SemiBold().FontSize(titleSize);
                        colObs.Item().PaddingLeft(textXS).Text(_dto.Observacion.ToUpper()).Justify();
